<script setup>
import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{apiClient,currentApiCacheScope}from'../../utils/api.js';import WbPublishMediaSummary from './WbPublishMediaSummary.vue';
const props=defineProps({sourceJobId:{type:Number,required:true},draftId:{type:Number,required:true},action:{type:String,default:'republish'}}),emit=defineEmits(['close','submitted']);const review=ref(null),loading=ref(false),error=ref('');
async function load(){const scope=currentApiCacheScope();loading.value=true;error.value='';try{const r=await apiClient.post('/api/wb/product-operation/review',{source_job_id:props.sourceJobId,draft_id:props.draftId,action:props.action});if(scope===currentApiCacheScope())review.value=r;}catch(e){if(scope===currentApiCacheScope())error.value=e.message;}finally{loading.value=false;}}
async function submit(){if(!review.value?.ok)return;const scope=currentApiCacheScope();loading.value=true;try{const r=await apiClient.post('/api/wb/product-operation/submit',{source_job_id:props.sourceJobId,draft_id:props.draftId,action:props.action,revision:review.value.revision,review_hash:review.value.review_hash,confirmed:true});if(scope===currentApiCacheScope()){ElMessage.success('操作已保存到上架记录，等待核对平台结果。');emit('submitted',r.job);}}catch(e){if(scope===currentApiCacheScope()){error.value=e.message;review.value=null;}}finally{loading.value=false;}}
onMounted(load);
</script>
<template><el-dialog :model-value="true" :title="action==='archive'?'归档到 WB 回收站':'恢复原商品并重新上架'" width="min(900px,95vw)" :close-on-click-modal="false" @close="emit('close')"><div v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="review"><el-alert :title="review.message" type="warning" :closable="false"/><p>店铺：{{review.shop_name}} · 草稿版本 {{review.revision}}</p><p v-if="review.action!=='archive'&&review.variants.length>1">商品组合：{{review.strategy==='independent'?'分别作为独立商品':'合并为一个商品'}}</p><p v-for="item in review.targets" :key="item.nm_id">{{item.vendor_code}} · WB {{item.nm_id}} · {{item.location==='trash'?'回收站':'商品库'}}</p><section v-for="(row,index) in review.variants" :key="index"><h4>{{row.card.title}}</h4><p v-if="action!=='archive'">{{row.card.sizes.map(s=>'¥ '+s.price).join(' / ')}} CNY</p><WbPublishMediaSummary :row="row"/></section><el-alert v-for="message in review.errors" :key="message" :title="message" type="error" :closable="false"/></template></div><template #footer><el-button @click="emit('close')">返回编辑</el-button><el-button :loading="loading" @click="load">重新核对</el-button><el-button type="danger" :disabled="!review?.ok||loading" @click="submit">{{action==='archive'?'确认归档':'确认恢复并提交'}}</el-button></template></el-dialog></template>
